# Generated by Gemini

import numpy as np
import matplotlib.pyplot as plt
from scipy.fft import rfft, rfftfreq

t = np.linspace(0, 2, 1000, endpoint=False)  # 500 Hz sampling
rng = np.random.default_rng(0)
clean = 1.5*np.sin(2*np.pi*5*t) + 0.8*np.sin(2*np.pi*22*t)
signal = clean + rng.normal(0, 1.0, len(t))

freqs = rfftfreq(len(t), d=t[1] - t[0])
amplitudes = np.abs(rfft(signal)) * 2 / len(t)
amplitudes[0] /= 2  # DC component scaling (good practice, though near 0 here)

top2_idx = np.argsort(amplitudes)[-2:]
dom_freqs = freqs[top2_idx]
dom_amps = amplitudes[top2_idx]
print("Dominant frequencies (Hz):", np.sort(dom_freqs))
for f_val, a_val in sorted(zip(dom_freqs, dom_amps)):
    print(f"  {f_val:.1f} Hz -> amplitude = {a_val:.3f}")

fig, (ax1, ax2) = plt.subplots(2, 1, figsize=(10, 6.5))

# Top panel: Time domain (first 1.0 s for clarity, or full 2.0 s)
ax1.plot(t, signal, color='steelblue', alpha=0.65, lw=1.0, label='Noisy signal ($\\sigma = 1.0$)')
ax1.plot(t, clean, color='black', ls='--', lw=1.5, label='Underlying clean sum (5 Hz + 22 Hz)')
ax1.set_xlim(0, 1.0)
ax1.set_xlabel('Time $t$ (s)')
ax1.set_ylabel('Amplitude')
ax1.set_title('Time Domain: Noisy Signal (First 1.0 s Shown)')
ax1.grid(True, alpha=0.3)
ax1.legend(loc='upper right')

# Bottom panel: Frequency domain (zoomed to 0–60 Hz)
ax2.plot(freqs, amplitudes, color='darkorange', lw=1.5, label='FFT amplitude spectrum')
ax2.scatter(dom_freqs, dom_amps, color='crimson', zorder=5, s=60, label='Detected peaks')

for f_val, a_val in zip(dom_freqs, dom_amps):
    ax2.annotate(
        f'{f_val:.0f} Hz\n(amp = {a_val:.2f})',
        xy=(f_val, a_val),
        xytext=(f_val + 2.5, a_val - 0.1),
        fontsize=9.5,
        fontweight='bold',
        color='crimson',
        arrowprops=dict(arrowstyle='->', color='crimson', lw=1.0)
    )

ax2.set_xlim(0, 60)
ax2.set_ylim(0, max(amplitudes) * 1.2)
ax2.set_xlabel('Frequency (Hz)')
ax2.set_ylabel('Amplitude')
ax2.set_title('Frequency Domain: Single-Sided Amplitude Spectrum (`rfft`, Zoomed 0–60 Hz)')
ax2.grid(True, alpha=0.3)
ax2.legend(loc='upper right')

plt.tight_layout()
plt.savefig('rfft_visualization.png', dpi=150)
plt.show()
